-- Preview storyboard (hover timeline thumbnails) for every video table.
-- Shape (jsonb): {"interval": 10, "tileW": 160, "tileH": 90, "cols": 10,
--                 "rows": 10, "count": 123, "sheets": ["url1", "url2"]}
-- Generated by scraper/thumbnails.py (ffmpeg sprite extraction at ingest),
-- rendered by the frontend VideoPlayer for zero-latency timeline hover
-- previews. NULL = not generated yet; the player falls back to seek-based
-- previews for those rows.

ALTER TABLE scraper.videos                    ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.japanese_videos           ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.myanmar_videos            ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.onlyfans_videos           ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.voyeurhouse_videos        ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.hotscopesvoyeurhouse_videos ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.reallifecamto_videos      ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.hotscopesspygasm_videos   ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.hotscopesreallifecam_videos ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;
ALTER TABLE scraper.chinese_videos            ADD COLUMN IF NOT EXISTS preview_thumbs JSONB;

CREATE INDEX IF NOT EXISTS idx_videos_missing_preview
    ON scraper.videos (scraped_at DESC) WHERE preview_thumbs IS NULL AND full_video_url IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_chinese_missing_preview
    ON scraper.chinese_videos (scraped_at DESC) WHERE preview_thumbs IS NULL AND full_video_url IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_myanmar_missing_preview
    ON scraper.myanmar_videos (scraped_at DESC) WHERE preview_thumbs IS NULL AND full_video_url IS NOT NULL;
